import { useState } from "react";
import { Button, Card, Disclosure, Divider, PageHeader, StatusPill, Typography } from "@autograph/components";
import "./app.css";

const money = (value: number) => new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 }).format(value);

export default function VendorSpendForecastReview() {
  const [reviewed, setReviewed] = useState(false);
  return <main className="review-page"><div className="review-shell">
    <PageHeader title="Vendor spend forecast review" subtitle="Review the FY27-Q1 outlook before Northstar Cloud's renewal. Forecast figures are advisory and all actions are simulation only." actions={<StatusPill label="Needs review" detail="Renewal" tone="warning" />} />
    {reviewed ? <Card className="simulation-result"><div className="result-row"><div><Typography variant="body-strong">Review simulation recorded</Typography><Typography variant="caption" tone="secondary" className="result-copy">The prototype now shows this forecast as reviewed for the current session. No forecast, commitment, or provider record changed.</Typography></div><Button size="sm" intent="secondary" onClick={() => setReviewed(false)}>Reset simulation</Button></div></Card> : null}
    <section className="identity-row" aria-label="Vendor and review period"><div><Typography variant="micro" tone="muted">Vendor</Typography><Typography as="h2" variant="section-title" className="identity-title">Northstar Cloud</Typography><Typography variant="caption" tone="secondary">V-21 · Owner: Infrastructure</Typography></div><div className="period-block"><Typography variant="micro" tone="muted">Review period</Typography><Typography variant="title">FY27-Q1</Typography><Typography variant="caption" tone="secondary">Renewal due Nov 15, 2026</Typography></div></section>
    <div className="content-grid"><section className="evidence-stack" aria-label="Forecast evidence">
      <div className="measure-grid">
        <Card><Typography variant="micro" tone="muted">Actual · prior quarter</Typography><Typography as="div" variant="page-title" className="measure-value">{money(84000)}</Typography><Typography variant="caption" tone="secondary">Completed-quarter actual spend</Typography></Card>
        <Card><Typography variant="micro" tone="muted">Actual · current QTD</Typography><Typography as="div" variant="page-title" className="measure-value">{money(31000)}</Typography><Typography variant="caption" tone="secondary">Recorded in FY27-Q1 to date</Typography></Card>
        <Card><Typography variant="micro" tone="muted">Expected charges</Typography><Typography as="div" variant="page-title" className="measure-value">{money(96000)}</Typography><Typography variant="caption" tone="secondary">Forecast total, not an actual</Typography></Card>
        <Card><Typography variant="micro" tone="muted">Committed</Typography><Typography as="div" variant="page-title" className="measure-value">{money(72000)}</Typography><Typography variant="caption" tone="secondary">Existing commitment within forecast</Typography></Card>
      </div>
      <Card title="Forecast bridge"><div className="bridge-row"><div><Typography variant="caption" tone="secondary">Expected charges</Typography><Typography variant="title">{money(96000)}</Typography></div><Typography variant="title" tone="muted">−</Typography><div><Typography variant="caption" tone="secondary">Committed</Typography><Typography variant="title">{money(72000)}</Typography></div><Typography variant="title" tone="muted">=</Typography><div><Typography variant="caption" tone="secondary">Uncommitted exposure</Typography><Typography variant="title">{money(24000)}</Typography></div></div><Divider className="bridge-divider" /><Typography variant="caption" tone="secondary">The {money(12000)} plan variance sits inside a larger {money(24000)} uncommitted portion of the expected forecast.</Typography></Card>
      <Card><Disclosure defaultOpen summary={<Typography variant="body-strong">Forecast assumption</Typography>} summaryClassName="assumption-summary"><div className="assumption-body"><Typography variant="title">Annual renewal at 8% uplift</Typography><Typography variant="caption" tone="secondary">Advisory input supporting expected charges. Confirm the uplift and renewal scope before relying on the forecast.</Typography></div></Disclosure></Card>
    </section><aside aria-label="Variance decision"><Card title="Variance to plan" className="decision-card"><Typography as="div" variant="page-title" className="variance-value">+{money(12000)}</Typography><Typography variant="body-strong">Expected charges are above plan</Typography><Typography variant="body" tone="secondary" className="decision-copy">The variance is actionable because the renewal is still marked for review and {money(24000)} of expected charges are not represented by the commitment.</Typography><div className="watch-box"><div className="watch-heading"><Typography variant="micro" tone="muted">Renewal watch item</Typography><StatusPill label="Needs review" tone="warning" /></div><Typography variant="body-strong">Due Nov 15, 2026</Typography><Typography variant="caption" tone="secondary">Validate the 8% uplift, confirm what the {money(72000)} commitment covers, and reconcile the remaining {money(24000)} before renewal.</Typography></div><Divider className="action-divider" /><Button intent="primary-strong" className="review-action" disabled={reviewed} onClick={() => setReviewed(true)}>{reviewed ? "Review simulated" : "Mark review complete"}</Button><Typography variant="caption" tone="muted" className="simulation-note">Simulation only. This does not change the forecast, commitment, watch item, or renewal.</Typography></Card></aside></div>
  </div></main>;
}

.review-page { min-height: 100vh; background: var(--color-bg-page); color: var(--color-text-primary); padding: var(--space-8); }
.review-shell { width: 100%; max-width: 1180px; margin: 0 auto; display: grid; gap: var(--space-6); }
.simulation-result { border-color: var(--color-status-success); }
.result-row { display: flex; align-items: center; justify-content: space-between; gap: var(--space-4); }
.result-copy { margin: var(--space-1) 0 0; }
.identity-row { display: flex; align-items: end; justify-content: space-between; gap: var(--space-6); padding: var(--space-4) 0; border-top: 1px solid var(--color-border-subtle); border-bottom: 1px solid var(--color-border-subtle); }
.identity-title, .measure-value, .variance-value { margin: var(--space-1) 0 0; }
.period-block { text-align: right; }
.content-grid { display: grid; grid-template-columns: minmax(0, 1.7fr) minmax(320px, 0.9fr); gap: var(--space-6); align-items: start; }
.evidence-stack { display: grid; gap: var(--space-4); }
.measure-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-4); }
.bridge-row { display: grid; grid-template-columns: 1fr auto 1fr auto 1.2fr; gap: var(--space-3); align-items: center; }
.bridge-divider { margin: var(--space-4) 0; }
.assumption-summary { padding: var(--space-1) 0; }
.assumption-body { display: grid; gap: var(--space-1); padding: var(--space-3) 0 0 var(--space-5); }
.decision-card { position: sticky; top: var(--space-6); }
.variance-value { color: var(--color-status-warning-ink); }
.decision-copy { margin: var(--space-2) 0 var(--space-4); }
.watch-box { display: grid; gap: var(--space-2); padding: var(--space-4); border-radius: var(--radius-control); background: var(--color-status-warning-bg); }
.watch-heading { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3); }
.action-divider { margin: var(--space-5) 0 var(--space-4); }
.review-action { width: 100%; }
.simulation-note { display: block; margin-top: var(--space-2); }
@media (max-width: 900px) { .content-grid { grid-template-columns: 1fr; } .decision-card { position: static; } }
@media (max-width: 620px) { .review-page { padding: var(--space-4); } .measure-grid { grid-template-columns: 1fr; } .identity-row, .result-row { align-items: flex-start; flex-direction: column; } .period-block { text-align: left; } .bridge-row { grid-template-columns: 1fr; } .bridge-row > p { display: none; } }
